const {vec} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bob.obj");

const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};

const originalPts = normalizeVectors(vertices.map(vertex => vec(...vertex)));
let pts = originalPts.slice();

// Dimension-agnostic bounding box volume calculator
const boundingBoxVolume = vectors => {
    const dim = vectors[0].components.length;
    const min = Array(dim).fill(Infinity);
    const max = Array(dim).fill(-Infinity);
    for (const point of vectors) {
        for (let d = 0; d < dim; d++) {
            min[d] = Math.min(min[d], point.components[d]);
            max[d] = Math.max(max[d], point.components[d]);
        }
    }
    let vol = 1;
    for (let d = 0; d < dim; d++) {
        vol *= (max[d] - min[d]);
    }
    return vol;
};

const originalVolume = boundingBoxVolume(originalPts);
if (!(originalVolume > 0)) throw new Error("The initial point cloud must have a non-zero bounding-box volume");

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const sigma = 0.05;
const maxDegree = Math.max(1, ...Object.keys(graph.vertices).map(id => graph.getNeighbors(id).length));
const maxAlpha = 0.9 / maxDegree;
let alpha = Math.min(0.05, maxAlpha);
let ite = 1; // Default iterations per click

const points = pts.map(point => point.toArray());
const pointPlot = IO.plotPointCloud(points, {color: [0.5, 0.5, 0.5]});
const rasterPlot = IO.raster(points, faces, {color: [0.5, 0.5, 0.5]});

const updatePlot = () => {
    const newPoints = pts.map(point => point.toArray());
    pointPlot.update(newPoints, {color: [0.5, 0.5, 0.5]});
    rasterPlot.update(newPoints, faces, {color: [0.5, 0.5, 0.5]});
    pointPlot.render();
    rasterPlot.render();
};

const takeFlowStep = () => {
    const dim = pts[0].components.length;

    // 1. Update graph vertices and compute dynamic Laplacian
    for (let i = 0; i < pts.length; i++) graph.getVertex(i).vertex = pts[i];
    const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));

    // 2. Explicit Dirichlet energy minimization step (Laplacian smoothing)
    const coordinates = Array(dim).fill(0).map((_, d) => vec(...pts.map(point => point.components[d])));
    const flowedCoordinates = coordinates.map(coordinate =>
        coordinate.sub(laplacian.prodVec(coordinate).scale(alpha))
    );
    let flowedPts = pts.map((_, i) => vec(...flowedCoordinates.map(coordinate => coordinate.components[i])));

    // 3. Center to origin
    const mean = flowedPts.reduce((sum, point) => sum.add(point), vec.zero(dim)).scale(1 / flowedPts.length);
    flowedPts = flowedPts.map(point => point.sub(mean));

    // 4. Smooth Lagrange Multiplier Constraint Projection via Radial Dilation Gradient
    const currentVolume = boundingBoxVolume(flowedPts);
    if (!Number.isFinite(currentVolume) || currentVolume <= 0) {
        console.error("Flow stopped because volume became degenerate");
        return;
    }

    const volumeError = originalVolume - currentVolume;

    // Smooth constraint gradient field: g_i = position vector from center (uniform N-dim dilation)
    const grads = flowedPts.map(pt => pt.scale(dim));

    // Denominator = sum of squared gradient norms across all points
    const denom = grads.reduce((sum, g) => sum + g.squareLength(), 0);
    const lambda = denom > 1e-12 ? volumeError / denom : 0;

    // Project/correct vertex positions smoothly along the radial gradient field
    flowedPts = flowedPts.map((pt, i) => pt.add(grads[i].scale(lambda)));

    // Re-center and update
    const finalMean = flowedPts.reduce((sum, point) => sum.add(point), vec.zero(dim)).scale(1 / flowedPts.length);
    pts = flowedPts.map(point => point.sub(finalMean));
};

// Run multiple iterations per click
const runIntegration = () => {
    for (let i = 0; i < ite; i++) {
        takeFlowStep();
    }
    updatePlot();
};

const resetSimulation = () => {
    pts = originalPts.slice();
    updatePlot();
};

resetSimulation();

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => rasterPlot},
    ]},
    {type: "group", value: () => [
        {type: "button", value: () => ({title: "Reset", onClick: resetSimulation})},
        {type: "button", value: () => ({title: "Integrate", onClick: runIntegration})},
    ]},
    {type: "slider", value: () => ({
        min: 0,
        max: maxAlpha,
        step: maxAlpha / 100,
        value: alpha,
        title: "Alpha:",
        onChange: value => { alpha = value; },
    })},
    {type: "slider", value: () => ({
        min: 1,
        max: 100,
        step: 1,
        value: ite,
        title: "Iterations (ite):",
        onChange: value => { ite = Math.round(value); },
    })},
);
ui;
